// Кухня в Ё Конструкторе (основа 08.10.2026; конструктив по проектам Базиса цеха — разбор базы кухонь цеха 09.10.2026).
// Кухонный корпус — обычный модуль студии с пометкой kitchen (нижний, навесной, пенал, антресоль): наполнение, фасады, петли,
// смета и раскрой работают как у шкафов. Здесь — только кухонное: регламенты, опоры с клипсами и цоколем, навесы, ниши техники,
// столешница как отдельный объект и шаблоны для палитры.
// Источник чисел: 30 кухонь, 372 модуля Базиса (Кухни\etalon\archetypes.md, отчёты разведки 09.10.2026). Оси Базиса = оси студии
// (X вправо, Y вверх, фасады на +Z), проверено снимком на кухне 2777.
import { facadeSideToFloor, facadeSideErrors, type FacadeSides } from './kitchenFacadeSides';
import { OVEN_BASE_NICHE } from './ovenDimensions';
import { sinkParts, worktopCutErrors } from './premialSink';
import {ovenErrors,ovenParts,type OvenSpec} from './kitchenOven';
import { CONFIRMAT_QUATS, RULES, type GolaCut, type Module, type Part } from "./model";
import { setEdges, edgeDirs } from "./edges";
import { axisLayout, type FirmaxBox } from "./kitchenDrawers";
import { RAFIX, RAFIX_MODEL, rafixZs, type KitchenRafix, type RafixGrid } from "./kitchenRafix";
import { kitchenDividerErrors, mirrorDivider, parseDivider, type KitchenDivider } from "./kitchenDivider";
import { allegroErrors, parsePremialPullout, type PremialPullout } from './premialPullout';

export type KitchenRole = "base" | "wall" | "tall" | "antresol";
export type ApplianceKind = "sink" | "oven" | "microwave" | "dishwasher" | "hob" | "hood" | "fridge";
export type KitchenSpec = { role: KitchenRole; appliance?: ApplianceKind;
  facadeSides?: FacadeSides;
  oven?: OvenSpec;
  premialPullout?: PremialPullout;
  /** Цоколь модуля: высота (Базис 95, на 5 мм ниже дна) и есть ли он у этого модуля (сплошной цоколь ряда — у крайнего). */
  plinth?: { height: number; off?: boolean; clips?: boolean;
    /** Корпус без опор (цоколь — деталь самого модуля): отступ цоколя от переда корпуса, если не RULES.plinthInset 2 (Базис k20 m09: 16). */
    inset?: number };
  /** Корпус приподнят без опор, и в модуле Базиса под дном есть фронтальная панель ЛДСП (цоколь/планка под другим именем) —
   *  студия ставит «Цоколь» по высоте подъёма. Без флага у кухни такого цоколя нет (у навесного фасад свисает ниже дна). */
  lowFront?: boolean;
  /** Пакет 3: крепёж щита под дном по проекту Базиса (k14 m03) — конфирматы через боковины в торцы щита (side: мм от низа щита) и через
   *  дно в его верхний торец (top: мм от концов щита, парой). Нет — щит без крепежа, как раньше. */
  lowFrontConf?: { side: number[]; top: number[] };
  /** Низ навесного без опор (Базис): дно поднято на plinthHeight, стандартного цоколя нет. front — фронтальная панель ЛДСП под дном
   *  (в Базисе «Фронтальная», «ФП» — закрывает низ, как цоколь) с утопанием от лица боковин; без front панели нет.
   *  doorsToFloor — фасады опущены до низа модуля (корпус поднят, фасад закрывает подсветку: k23, k28, k30). */
  raise?: { front?: number; doorsToFloor?: boolean;
    /** Планка ЛДСП лёжа у задней кромки под поднятым дном (между боковинами, y 0…16, от задней кромки на depth; конфирматы через боковины
     *  по правилу стыка — одна точка посередине у планки до 120). По базе — 7 навесных с поднятым дном: k04 m06 (50), k04 m09 (100),
     *  k08 m08, k10 m07, k14 m03 (50), k18 m12 (60), k32 m13 (50); кромка перед и зад (5 из 7), k10 — без, k32 — по кругу (edgeScheme.parts). */
    plank?: { depth: number };
    /** Крепёж фронтальной панели под дном по Базису (pkg-hoodbox; 4 из 6 навесных с панелью: k14 m03, k15 m08, k18 m12, k22 m10): side — конфирматы
     *  через боковины в торцы панели, мм от её низа; top — сверху через дно: конфирматы (conf, k14) или эксцентрик в тыльной пласти панели
     *  в 34 от её верха + шкант 8×30 на 32 ближе к середине (ecc); xs — от левого конца панели, xr — от правого, mid — посередине. */
    conf?: { side?: number[]; top?: { kind: "conf" | "ecc"; xs: number[]; xr?: number[]; mid?: true; dowels?: false }; /** D5 конфирматов в панель, если не как у корпуса (k22 m10: 42) */ depth?: number } };
  /** Дно короче спереди на столько мм (Базис k06, k10, k15: 24,5 — ниша под подсветку у лица навесного); по умолчанию 0. */
  bottomFront?: number;
  /** Дно короче сзади (Базис: навесной под вытяжку, дно перед ХДФ — k08 m10, k04, k13, k14: 20). */
  bottomBack?: number;
  /** Крыша короче сзади (Базис k33, k34: 20 — крыша перед ХДФ, ХДФ проходит за ней); backTopGap — ХДФ в паз до верха модуля минус столько мм (k33/k34: 1). */
  topBack?: number;
  backTopGap?: number;
  /** Набивной ХДФ с разными отступами [снизу, сверху] от низа и верха корпуса (Базис k32 m06: 2 и 4 при боковых 1,5). */
  backGapY?: [number, number];
  /** Модуль без дна (сушка k34 m04): ХДФ от низа модуля плюс столько мм (k34: 1). */
  backBottomGap?: number;
  /** Вырезы в обоих верхних углах ХДФ (Базис k33, k34: 25×45 — ХДФ проходит за крышей): ширина по X, высота от верха ХДФ. */
  backNotch?: { width: number; height: number };
  /** Стыки дна/крыши без крепежа в проекте Базиса («bottom:left» и т. п., k08 m10, k14 m06) — студия крепёж не ставит. */
  jointNone?: string[];
  /** Крепёж стыков дна/крыши с боковинами по Базису: ключ «bottom:left» и т. п. → [от задней кромки, от передней кромки детали], мм.
   *  Третье число — третий конфирмат у задней кромки (от неё; k25 m16 крыша, k31 m08 дно: 8 при паре 74/54). */
  jointZ?: Record<string, [number, number] | [number, number, number]>;
  // Крепёж стяжки на ребре по Базису (конфирматы через боковины и через крышу/дно) — в самой стяжке: Module.rails[].confY и topConf
  // (одно правило для нижних, навесных и антресолей; слияние n4-base, n4-wall).
  /** Стяжка на дне навесного на эксцентриках и шкантах снизу по Базису (n4-wall; k04 m08, k31): ключ — место стяжки; ecc и dowel —
   *  мм от левого конца стяжки; face — пласть стяжки с бочонком D15×12 (front — к фасаду, back — к стене). */
  railUnder?: Record<string, { ecc: number[]; dowel: number[]; /** пакет 0: точки правой половины стяжки — мм от её ПРАВОГО конца (переживают смену ширины) */ eccR?: number[]; dowelR?: number[]; face: "front" | "back" }>;
  /** Крепёж корпуса по проекту Базиса (одно поле на один факт, n7-spec-dedupe): false — крепежа нет вовсе (ни конфирматов, ни эксцентриков,
   *  ни шкантов, ни полкодержателей; только k32 — 22 модуля); 'pins' — нет крепежа стыков (конфирматы, эксцентрики, шканты), полкодержатели
   *  остаются (бывшее noFasteners: n3-wall, n3-antresol). Без поля / true — как у шкафов. Читать через fastenersMode(k). */
  fasteners?: boolean | "pins";
  /** Сушка навесного — элементы с сеткой Базиса (набор SU01/03: держатели, решётки, поддоны): x — от боковины side, y — от низа, z — от задней кромки. */
  dryer?: { name: string; /** сетка библиотеки Базиса; нет — у Базиса элемент без геометрии (k01, k02, k06, k08): точка и строка спецификации */ mesh?: string; side: "left" | "right"; x: number; y: number; z: number; quat: [number, number, number, number];
    /** элемент комплекта сушки, который Базис пишет в «прочее» («10x13», «Вращение», «Отверстие 3х2» — F_DRYER): деталь «прочее»;
     *  hole — отверстие Базиса из этой точки в боковину [d, глубина] (у «10x13» k25 m14 — D10×13), без него отверстия нет, как в Базисе */
    fix?: true; hole?: [number, number] }[];
  /** Имя крепежа корпуса по проекту Базиса, если это не «Конфирмат 7х50» (k33, k34: «Евровинт 6х50») — в деталях и смете. */
  confirmatName?: string;
  /** Глубина присадки по проекту Базиса, если она не типовая: confirmat — D5 в торец (обычно 35; k33/k34 «Евровинт 6х50» — 36), pin — D5 под полкодержатель (обычно 12; k33/k34 — 9). */
  drill?: { confirmat?: number; pin?: number };
  /** Присадка эксцентрика по проекту Базиса, если не типовая (k33/k34 «Стяжка Макмарт Ø15»): глубина бочонка D15 (13 вместо 12),
   *  шток [D, глубина] ([7, 28] вместо [8, 34]), в стойку D5 (9 вместо 12), шкант в стойку D8 (11 вместо 12);
   *  bottomOut — бочонок дна с наружной (нижней) пласти; topOut — бочонок крыши с наружной (верхней) пласти (k07, n4-wall). */
  ecc?: { barrel?: number; stem?: [number, number]; side?: number; dowelSide?: number; bottomOut?: boolean; topOut?: boolean };
  /** Вырез в заднем верхнем углу боковины навесного/антресоли (Базис k32: 100×20 — контур боковины из 6 точек): height — от верха, depth — от задней кромки. */
  sideNotch?: Partial<Record<"left" | "right", { height: number; depth: number }>>;
  /** Навесы ABS L/R: по умолчанию есть у навесных и антресолей; false — навешивание иначе (планка, шина, ранние проекты без навесов);
   *  true у пенала — пенал на навесах, как в проекте Базиса (k23 m04, k18 m21). */
  hangers?: boolean;
  /** Положение навесов, как в проекте Базиса (если не по правилу 15 ниже верха / 20 от задней кромки / на внутренней грани боковины):
   *  [ниже верха боковины, от задней кромки, внутрь от внутренней грани боковины], мм — по каждой стороне. Отрицательное «ниже верха» —
   *  навес выше корпуса (так стоит в части проектов Базиса; отверстий в боковине тогда нет, как и у Базиса). */
  hangerAt?: { left: [number, number, number]; right: [number, number, number]; caps?: { left: [number, number, number]; right: [number, number, number] } };
  /** Набивной ХДФ стоит с зазором от задней кромки корпуса, мм (k01 m14, k01 m10 — 2, так в проекте Базиса). Без поля — вплотную. */
  backAir?: number;
  /** Служебные сквозные отверстия, как в проекте Базиса (k28 m14: D10 под провод в боковине и дне): точка входа, направление внутрь
   *  детали, диаметр, глубина. В смету не идут (у Базиса это служебная запись). */
  svcHoles?: { at: [number, number, number]; dir: [number, number, number]; d: number; depth: number }[];
  /** Стяжка соседних модулей в Gola (Базис «5»: служебная запись + сквозное D5 на толщину боковины; по всей базе 23 боковины
   *  в k10, k15, k17, k30, k21, k31 — все в остром верхнем углу среднего выреза Gola: на его верхней кромке, в глубине выреза от переднего торца;
   *  у соседа — встречное, винт стягивает боковины за профилем C). Стороны — по проекту Базиса (в k06, k21 m03, k23, k27, k31 НМ
   *  стяжек нет), значение — направление сверления по X (+1 — с левой пласти). depth — от переднего торца боковины, если не равна
   *  глубине выреза (k17: 27 при вырезе 26). Без поля — нет. */
  golaTies?: { left?: 1 | -1; right?: 1 | -1; depth?: number };
  /** Глухие фасады рядом с ящиками — без петель, направляющих и короба, как в проекте Базиса (k29 m03: фасад 102–593 под двумя
   *  ящиками Axis). Низ и верх от пола модуля, ширина и вынос — как у фасадов ящиков. Без поля — нет. */
  blindFronts?: { y0: number; y1: number }[];
  /** Конфирматы стяжки с соседним корпусом, как в проекте Базиса (k15 m12): изнутри через боковину наружу — сторона, высота,
   *  от задней кромки боковин. Без поля их нет. */
  outConf?: { side: "left" | "right"; y: number; z: number }[];
  /** Точки крепления крепежа, чьё отверстие и в проекте Базиса вскрывает паз подсветки (k31, k28 m12): только это пересечение
   *  подписывается «как в проекте Базиса» (collisions.ts). Ставит импорт по двойнику в Базисе (compare.ts grooveTwins). */
  grooveHoles?: GrooveHole[];
  /** @deprecated Признак «из Базиса» живёт в Module.bazis (isBazisModule в project.ts — единственная точка); parse переносит
   *  kitchen.bazis → m.bazis. Поле оставлено в типе до перехода pricing.ts / App.tsx / KitchenPanel.tsx (A3/A5), потом удалить. */
  bazis?: boolean;
  /** Дно под боковинами на эксцентриках (Базис k16, k28, k31; jointFastening bottom:left/right = eccentric): отступы стяжек
   *  от задней и передней кромки дна, мм (у Базиса несимметрично: сзади на 20 больше — за пазом ХДФ). */
  /** Пакет 3 (m_PINS): полкодержатели стойки на своих местах — [от заднего, от переднего торца полки], мм, если у левой и правой
   *  по-разному (k16 m03: левая 64,5/64,5, правая — общее правило shelfPinInset/shelfPinInsetFront). Нет стороны — общее правило. */
  pinSide?: { left?: [number, number]; right?: [number, number] };
  /** Пакет 3 (m_PINS): перфорация Базиса — ряды полкодержателей без полки, мм от низа каждой съёмной полки (по базе k26 m02/m03/m04:
   *  −100, −50, 50, 100); места по глубине — как у полки. */
  pinRows?: number[];
  underEcc?: { back: number; front: number;
    /** пакет 3: ещё эксцентрики без шканта — мм от задней кромки дна, по сторонам (по базе 8 у обеих: k27 m04/m05, k28 m08; у левой: k28 m12) */
    extra?: { left?: number[]; right?: number[] } };
  /** ХДФ в пазу: зазор до дна паза снизу и сверху, мм, как в проекте Базиса (k28 m10: 2,5 и 1); без поля — grooveClear с обеих сторон. */
  backClearY?: [number, number];
  // Глубина D5 конфирмата по проекту — только drill.confirmat (бывшее confDepth: k11 — 37, k31 — 42; parse-алиас в parseKitchenSpec).
  /** Опоры: отступы рядов от задней и передней кромки боковин и позиции по ширине (по умолчанию 70/70 от краёв дна, как в Базисе). */
  legs?: { back: number; front: number; side?: number; xs?: number[];
    /** Площадка опоры на 4 самореза 3×3 по квадрату 31×31 (Базис «3x3» у опор: k21, k24 — 6 модулей из 174 с опорами). */
    screws?: true;
    /** Левые опоры — той же сетки и поворота, что правые (часть проектов Базиса: k26, k27). */
    same?: true;
    /** Два ряда без третьего посередине и шире 1300 (широкие модули Базиса: мойка k28 m17 1480, остров k30 m01 1324): ряды — по
     *  отступу side от торцов, поэтому правые опоры идут за боковиной при смене ширины. */
    rows2?: true;
    /** Нерегулярная раскладка Базиса (17 модулей 10 кухонь: не сетка «ряды × перед/зад»): точки [x, z от задней кромки боковин]. */
    pts?: [number, number][];
    /** Пакет 0 (правило «от кромки детали + сторона»): позиции и точки ПРАВОЙ половины дна — мм от правого торца (x = W − v), чтобы
     *  при смене ширины правые опоры шли за правой боковиной, а не оставались на старом x. Импорт делит xs/pts по середине ширины. */
    xr?: number[]; ptsR?: [number, number][] };
  /** @deprecated Крепёж «Евровинт 6х50» (шаблоны «Т_» k33, k34: D8×16 + D5×36) — только confirmatName; parse переводит screw → confirmatName,
   *  поле в типе оставлено до перехода pricing.ts (A3: единый ключ сметы confirmat:<name>), потом удалить. */
  screw?: "euro-6x50";
  /** Как в Базисе — ничего сверх проекта (правило Макса): false — фасады без петель (15 модулей 12 кухонь Базиса: фасад есть, петель нет,
   *  студия строит ровно те же фасады). Флаг модуля: дверь, добавленная потом в студии, тоже будет без петель — см. KitchenPanel. */
  hinges?: false;
  /** Корпус без опор (33 модуля 13 кухонь Базиса: дно на полу или на своём цоколе) — не ошибка для кухни из Базиса. */
  noLegs?: true;
  /** Гвозди набивного ХДФ по Базису (11 навесных/антресолей k01, k03): ряды по периметру в 7,5 от края, round(W/125) и round(H/125)
   *  гвоздей (см. scripts/kitchen/recognize-nails.ts); q — поворот сетки по рядам, mesh — сетка Базиса. Нет — студия гвоздей не ставит.
   *  name — крепёж ХДФ по проекту вместо гвоздя (пакет 3: «Саморез 3,5х12 мм, Zn» — 86 шт. в 5 модулях k09/k24, по той же раскладке 3). */
  nails?: { mesh?: string; name?: string; q: Record<"bottom" | "top" | "left" | "right", [number, number, number, number]> };
  /** Ручка распашного фасада по проекту Базиса (k07, k09: 36 ручек «рейлинг 128/160»): горизонтальная — по центру ширины,
   *  вертикальная — у свободного края; dy — от низа (from "bottom") или верха фасада до точки ручки на лицевой плоскости.
   *  holes — отверстия под ручку, если они есть в проекте (k07: 2 × D5×18 насквозь, межосевое 160; у k09 отверстий нет).
   *  name — ручка Базиса: в смете строкой Базиса «bazis:ручка:<name>» (не ручкой студии сверху неё); mesh, quat — сетка библиотеки
   *  и поворот Базиса [w,x,y,z] в точке ручки; size — габарит сетки в её осях [вдоль, поперёк, вылет] (n4-wall). */
  handle?: { dy: number; from: "bottom" | "top"; horizontal: boolean; holes?: { d: number; depth: number; gap: number };
    name?: string; mesh?: string; quat?: [number, number, number, number]; size?: [number, number, number] };
  /** Дно под одной боковиной, другая опущена (8 модулей 5 кухонь Базиса): до низа дна (y0 = низ дна, k22 m01) или до пола (y0 = 10, k06 m01 —
   *  торцевая боковина закрывает опоры). Действует только с дном под боковинами (bottomUnder). */
  sideDown?: { side: "left" | "right"; y0: number };
  /** «8x45» Базиса в нижнем торце опущенной боковины: отступы от задней кромки (только если они есть в проекте; k05 m01). */
  sideScrews?: number[];
  /** false — у петель нет наколок D3×3 под планку, только чашка Ø35 (26 модулей 11 кухонь Базиса). */
  plateHoles?: false;
  /** Нижний на опорах: зазор верха фасадов от верха боковин и низа фасадов от низа дна, если не равен faceGap (k18 m03: 3 и 1,5 при 2; n3-base).
   *  faceBottom у корпуса без опор — низ фасадов от пола, мм, как в Базисе (над нишей под техникой — от дна; n3-tall). */
  faceTop?: number; faceBottom?: number;
  /** Фасад шире корпуса (свес за боковину, F_WIDE_FACADE): кромка фасадов крайней секции на right/left мм за наружной пластью боковины,
   *  а не на зазор внутри неё (антресоли k19 m03/m04 — свес 12,5 справа). Корпус и его детали — по ширине модуля, как в Базисе. */
  faceOver?: { left?: number; right?: number };
  /** Угловая мойка Базиса с фальшпанелью (n4-base): у края модуля в плоскости фасадов — фальш ЛДСП корпуса width мм (от низа дна до верха),
   *  рядом планка из фасадного материала strip мм; фасады — после них через faceGap, дверь у фальша на «Петля под фальшпанель»
   *  (точка — кромка двери, чашка в 22 от кромки, без наколок под планку). Только плоский фальш (k25 m02, k01 m03); Г-образный — нет. */
  faceFiller?: { side: "left" | "right"; width: number; strip?: number; /** планка по высоте фальша, а не фасадов (k28 m17) */ stripFull?: true;
    /** конфирматы через фальш, если они есть в проекте (k01 m03): bottom — в передний торец дна, x от края модуля со стороны фальша;
     *  side — в передний торец боковины, y от низа фальша. Нет поля — фальш без крепежа (k25 m02, k28 m17 — как в Базисе) */
    conf?: { bottom?: number[]; side?: number[];
      /** фальш из фасада (прямой глухой угол k02 m01): стяжка с соседним модулем, вставшим торцом к фальшу — конфирмат с тыла фальша
       *  наружу, [x от края модуля со стороны фальша, y от низа дна]; у Базиса оба отверстия (D8 и D5) записаны на самом фальше */
      back?: [number, number][] };
    /** D5 конфирматов фальша, если не как у корпуса (k02 m01: 33 при 35) */
    confDepth?: number;
    /** фальш из фасадного материала по высоте ряда дверей в плоскости фасадов (навесные/антресоли/пеналы: k06 m11, k22 m08; F_FILLER_FLAT, пакет 2);
     *  inset — отступ фальша от края модуля (k22 m08: 2), без поля — от края; дверь у фальша — через faceGap, как у мойки */
    facadeMat?: true; inset?: number };
  /** Доборная планка сбоку модуля Базиса (F_FILLER_STRIP, 16 модулей базы): снаружи боковины стоят планки ЛДСП 16 в плоскостях,
   *  параллельных фасадам (передняя — у лица корпуса), перед ними — планка из фасадного материала в плоскости фасадов. Корпус студии
   *  остаётся шириной между боковинами, модуль в ряду шире на ext (sideExtension). Высоты — от низа дна, z планок — от задней кромки
   *  боковин, конфирматы — из боковины в торец передней планки (головка на внутренней пласти), y от низа планки. */
  sideStrip?: KitchenSideStrip;
  /** Накладной ХДФ: зазоры снизу и сверху, если не равны боковому backGap (24 модуля 13 кухонь Базиса; k32 m06: 2 и 4 при 1,5). */
  backGaps?: { bottom: number; top: number };
  // Эксцентрик дна снизу (56 из 380 эксцентриков дна Базиса, 12 модулей 10 кухонь) — только ecc.bottomOut (бывшее eccBelow; parse-алиас).
  /** Рафиксы жёстких полок по сетке Базиса (kitchenRafix.ts); без поля — жёсткие полки на конфирматах/эксцентриках, как у шкафов. */
  rafix?: KitchenRafix;
  /** Точек крепежа на стык дна/крыши со стойкой (2 или 3); без поля — по правилу kitchenJointPoints. */
  jointPoints?: 2 | 3;
  /** Жёсткие полки (номера секции 1), у которых в Базисе нет крепежа к стойкам: студия его не добавляет. */
  bareShelves?: number[];
  /** Низ корпуса приподнят без опор, а панели под дном (цоколя — детали, закрывающей низ) в Базисе нет: открытая ниша под техникой
   *  или зазор. Студия не рисует цоколь под дном (правило шкафов «низ без ножек — цоколь» к такой кухне не применяется). */
  bareBottom?: true;
  /** Дно/крыша, у которых в Базисе нет крепежа к стойкам (ни конфирмата, ни эксцентрика, ни шканта): студия его не добавляет. */
  bareJoints?: ("bottom" | "top")[];
  /** Крепёж стыков со стойками по сетке Базиса, если она не как у модуля (отступы от заднего/переднего торца, штук на сторону):
   *  ключ — bottom, top или shelf:N (жёсткая полка секции 1). Пример: k23 — у крыши 104,5/64,5, у дна 64,5/64,5. */
  joints?: Record<string, RafixGrid>;
  /** Дубли Базиса: фурнитура (опора, конфирмат), которая в проекте Базиса стоит дважды в одной точке (k16 m01 — две опоры,
   *  k23 m14 — два конфирмата полки). Повторяем Базис: id детали студии, у которой есть второй экземпляр — в 3D и смете их столько же,
   *  сколько в Базисе; отверстие одно (второй раз то же отверстие не сверлится). Нет детали с таким id (после правки) — дубль не ставится. */
  dupParts?: string[];
  /** Фигурный контур Базиса в плане у горизонтальной детали (id детали → точки [x, z] от её заднего левого угла): вырез под вентиляцию
   *  в дне пенала (k23 m15/m16). Ставится, только если габарит контура совпадает с деталью; после смены размера — прямоугольник. */
  planContours?: Record<string, [number, number][]>;
  /** Кромка фигурной детали по отрезкам её контура (id → толщина на каждом отрезке planContours[id], 0 — без кромки), как в проекте
   *  Базиса. По базе (17 горизонталей с П-вырезом под воздуховод в 13 навесных): стенки и дно выреза кромлены в 8 (k04, k05, k10, k18,
   *  k28, k30, k31 — своей толщиной: k10 0,5 при корпусе 0,4), не кромлены в 9 (k06, k15, k22, k25, k27, k24); наружные торцы у боковин —
   *  по правилу схемы (k18 m12, k30 m09 дно — кромлены). Кромка детали по направлениям (edge, edgeLen) и бирки считаются отсюда (contourEdgeLens). */
  contourEdges?: Record<string, number[]>;
  /** Короб под вытяжку навесного (pkg1; разбор базы — scripts/kitchen/hoodBox.ts: 15 навесных, 19 коробов): две стенки ЛДСП по оси x между
   *  горизонталями и фронт по оси z: накладной на торцы стенок (12 из 15, over — свес за стенки) или вкладной между ними заподлицо (3).
   *  Правила, а не координаты Базиса (пакет 0 — модуль переживает смену ширины/высоты): w — ширина по наружным граням стенок (ширина вытяжки,
   *  от модуля не зависит), dx — смещение центра короба от центра модуля (0 — по центру, 12 из 15); on/under — номер полки секции, на которой
   *  короб стоит / под которой кончается (нет — дно и крыша модуля), gapBelow/gapAbove — зазор от поверхности горизонтали до низа/верха стенок;
   *  z0/z1 — от задней кромки боковин. П-вырез горизонталей — planContours/contourEdges.
   *  Крепёж: конфирматы через горизонталь снизу/сверху в торцы стенок (conf.below/above — от задней кромки стенки) и с лица фронта в передние
   *  торцы стенок (conf.front — от низа стенки); без conf — по правилу стыка (confirmatInset от концов, середина у стенки выше 600).
   *  Фронт на эксцентриках (front.ecc — высоты от низа стенки; 12 из 15 модулей базы, конфирматы с лица — только k24): накладной — бочонок
   *  D15×12 в наружную пласть стенки в 34 от её переднего торца, шток D8×34 в торец стенки, D5×12 в тыл фронта; вкладной (k06, k17, k21) —
   *  бочонок в тыльную пласть фронта в 34 от стенки, шток в торец фронта, D5×12 в стенку. Шкант 8×30 рядом с каждым эксцентриком на 32 выше
   *  (у верхнего — на 32 ниже), 22 в торец, 12 в пласть; без шкантов — k05 (front.dowels: false).
   *  Полки по сторонам короба (shelves; 11 из 15): съёмная полка секции внутри высоты короба строится двумя кусками — от боковины до стенки
   *  короба с зазором gap (нет — как у боковины), у стенки передний угол срезан до apex от лица фронта (трапеция в плане, k05/k06/k15: 2,
   *  k18: 18, k21: −8); полкодержатели в стенке короба — pins от задней кромки полки (нет — как у боковины).
   *  ХДФ двумя кусками по сторонам короба (hdfSplit; k05, k15, k22, k27): до внутренней грани стенки минус 1, за коробом задника нет. */
  hoodBox?: { w: number; dx?: number; on?: number; under?: number; gapBelow: number; gapAbove: number; z0: number; z1: number;
    front: { mount: "overlay" | "inset"; over?: [number, number]; /** эксцентрики нижней половины стенки — от её низа; верхней — от верха (eccTop); средний (стенка выше 600: k05, k22, k30) — eccMid (пакет 0: переживают смену высоты) */ ecc?: number[]; eccTop?: number[]; eccMid?: true; /** бочонок с внутренней пласти стенки (k18 m12; обычно — с наружной) */ eccIn?: true; dowels?: false }; conf?: { front?: number[]; below?: number[]; above?: number[]; frontBelow?: number[]; frontAbove?: number[] };
    shelves?: { gap?: number; apex: number; pins?: [number, number] }; hdfSplit?: boolean;
    /** D5 конфирматов в торцы стенок короба, если не как у корпуса (k22 m10: 42 при 35; так же царга rails[].confDepth) */ confDepth?: number };
  /** ХДФ в пазу только от жёсткой полки (номер в секции 1) до верха: пенал под холодильник (k25 m10), ниже полки — ниша без задника.
   *  Низ ХДФ — низ полки плюс зазор паза (grooveClear), как в Базисе. Работает вместе с topBack/backTopGap и bottomBack. */
  backFromShelf?: number;
  /** Задняя стенка из ЛДСП (F_BACK_LDSP, пакет 4) — backType "board" у кухни Базиса: вкладная между боковинами, дном и крышей, тыльная
   *  пласть на inset от задней кромки боковин (k01 m08, k18 m16: 100; k18 m17/m18: 150), gap — зазоры до боковин/дна/крыши (k01 m08:
   *  0,5/1/0,5; k18: 0). Крепёж — рафиксы по сетке от кромок задника (правило «от кромки», пакет 0): side — в боковины (rear/front — от
   *  нижней/верхней кромки задника, n на сторону), bottom/top — в дно/крышу (от левой/правой кромки); корпус D20×13 с тыльной пласти
   *  задника в 9,5 от кромки, шток D5×13 в стойку в 8 от тыльной пласти (как у полок, kitchenRafix.ts). topShift — верхние рафиксы в проекте
   *  Базиса стоят дальше от тыльной пласти задника (k18: на 100, отверстие штока в крыше там же) — повторяем проект. caps — «8» Базиса:
   *  отверстие D8×16 с лицевой пласти задника в точке каждого рафикса (k18). Без rafix — задник без крепежа (k01 m08).
   *  Кромка задника — по edgeScheme.parts (k01 m08: по кругу 0,5), иначе без кромки (k18). Крыша перед утопленным задником — topBack. */
  backBoard?: { inset: number; gap?: { side: number; bottom: number; top: number }; rafix?: { side?: RafixGrid; bottom?: RafixGrid; top?: RafixGrid; topShift?: number; caps?: true } };
  /** Боковины разной глубины (F_ASYM_SIDES, пакет 4; 13 модулей базы — обход стояка, примыкание угла): одна боковина во всю глубину модуля,
   *  вторая (side) короче сзади на back, и всё между боковинами (дно, крыша, царги, полки, задник, опоры, фасады) стоит от её задней
   *  кромки — корпус глубиной depth − back, сдвинутый к лицу (k28 m16: левая короче на 203, k03 m03: правая на 54). ХДФ набивной
   *  на короткой боковине и дне, а в длинной — в пазу: заходит в неё на groove.into (k28: паз 6 − зазор 2 = 4, k03: 8 − 1 = 7).
   *  Правило «от кромки»: back — от задней кромки длинной боковины, ширина/высота меняются как у обычного корпуса. */
  sideRecess?: { side: "left" | "right"; back: number; groove?: { into: number } };
  /** Перегородка секций кухни Базиса (F_PARTITION, пакет 5): глубина и крепёж концов по проекту — kitchenDivider.ts. */
  divider?: KitchenDivider };

/** Корпус с боковинами разной глубины (kitchen.sideRecess): детали строятся для корпуса глубиной depth − back и сдвигаются к лицу на back;
 *  длинная боковина — во всю глубину, набивной ХДФ заходит в её паз на groove.into. Вызывается из parts() вместо обычной сборки. */
export function sideRecessParts(m: Module, build: (inner: Module) => Part[]): Part[] {
  const sr = m.kitchen!.sideRecess!, rec = sr.back, full = sr.side === "left" ? "right" : "left";
  const inner: Module = { ...m, depth: m.depth - rec, kitchen: { ...m.kitchen!, sideRecess: undefined } };
  const out = build(inner);
  for (const p of out) {
    p.position = [p.position[0], p.position[1], p.position[2] + rec];
    if (p.anchor) p.anchor = [p.anchor[0], p.anchor[1], p.anchor[2] + rec];
    if (p.model?.origin) p.model = { ...p.model, origin: [p.model.origin[0], p.model.origin[1], p.model.origin[2] + rec] };
    if (p.collide) p.collide = p.collide.map((c) => ({ ...c, position: [c.position[0], c.position[1], c.position[2] + rec] }));
    if (p.id === full) { p.size = [p.size[0], p.size[1], p.size[2] + rec]; p.position = [p.position[0], p.position[1], p.position[2] - rec / 2]; p.width += rec; }
    else if (p.id === "back" && p.material === "hdf" && sr.groove) {
      // кромка ХДФ у длинной боковины — в её пазу: от внутренней пласти боковины на groove.into (правило «от кромки»), другая — как построена
      const t = RULES.panel, x0 = p.position[0] - p.size[0] / 2, x1 = p.position[0] + p.size[0] / 2;
      const [a, b] = full === "right" ? [x0, m.width - t + sr.groove.into] : [t - sr.groove.into, x1];
      p.size = [b - a, p.size[1], p.size[2]]; p.position = [(a + b) / 2, p.position[1], p.position[2]]; p.width = b - a;
    }
  }
  return out;
}
/** Ошибки боковин разной глубины: укорочение от 20 мм и не глубже depth − 150, заход ХДФ в паз 0–8. */
export function sideRecessErrors(m: Module): string[] {
  const s = m.kitchen?.sideRecess; if (!s) return [];
  const e: string[] = [];
  if (!Number.isFinite(s.back) || s.back < 20 || s.back > m.depth - 150) e.push("Боковина короче сзади: от 20 мм и не глубже глубины корпуса минус 150.");
  if (s.groove && (!Number.isFinite(s.groove.into) || s.groove.into < 0 || s.groove.into > 8)) e.push("Боковина короче сзади: заход ХДФ в паз длинной боковины 0–8 мм.");
  return e;
}

/** Своя сетка крепежа стыка горизонтали (bottom/top/жёсткая полка) кухни Базиса; undefined — по общему правилу. */
export function kitchenJointGrid(m: Module, hid: string): RafixGrid | undefined {
  const j = m.kitchen?.joints; if (!j) return undefined;
  const key = hid === "bottom" || hid === "top" ? hid : hid.includes(":shelf:") && hid.startsWith(m.sections[0]?.id + ":") ? "shelf:" + hid.split(":shelf:")[1] : undefined;
  return key ? j[key] : undefined;
}

/** Точек крепежа на стык горизонтали кухни со стойкой — одно правило на все стыки (слияние n4-base и n4-tall):
 *  1) узкий стык (глубина joint до KITCHEN.narrowJoint, 120) в корпусе глубже него больше чем на narrowJoint — 1 точка посередине
 *     (Базис: 402 из 422 таких стыков с крепежом; мелкий корпус целиком, k08 m07 80–100 мм, — по п. 2);
 *  2) дно и крыша (bottomTop): свой счёт модуля из Базиса (kitchen.jointPoints), иначе 3 точки (третья посередине глубины) глубже
 *     KITCHEN.deepBottom (600) — 21 из 25 глубоких модулей Базиса с крепежом, до 600 — 2 (523 из 528); depth — корпус (по умолчанию)
 *     или дно под боковинами (9 из 9 днищ глубже 600 — по 3, ровно 600 k30 m03 — по 2): один порог на «глубокое дно» и «глубокий корпус»;
 *  3) остальные горизонтали — 2. Шкаф студии — всегда 2 (правила Базиса — только для кухонь). */
export function kitchenJointPoints(m: Module, depth = m.depth, joint?: number, bottomTop = true): 1 | 2 | 3 {
  if (!m.kitchen) return 2;
  if (joint !== undefined && joint <= KITCHEN.narrowJoint && m.depth - joint > KITCHEN.narrowJoint) return 1;
  if (!bottomTop) return 2;
  return m.kitchen.jointPoints ?? jointPointsRule(depth);
}
/** Правило кухни без своего счёта из Базиса: глубже KITCHEN.deepBottom (600) — 3 точки, иначе 2. */
export const jointPointsRule = (depth: number): 2 | 3 => (depth > KITCHEN.deepBottom ? 3 : 2);
export type WorktopCutout = { kind: "sink" | "hob"; x: number; z?: number; width: number; depth: number; fixture?: string; drainDrop?: number; tap?:boolean; plumbing?:boolean };
/** Материал столешницы. Старые: postforming (СКИФ, толщина вводится), ldsp (16+16), stone (искусственный камень).
 *  Задача Макса 19.10.2026 — толщина следует из материала: compact — компакт-плита 12; acrylic — акрил 12 в один слой или 40 с подклейкой;
 *  quartz — кварц 20; ЛДСП постформинг 38 — прежний postforming. */
export type WorktopMaterial = "postforming" | "ldsp" | "stone" | "compact" | "acrylic" | "quartz";
export type WorktopSpec = { material: WorktopMaterial; thickness: number; overhang: number; cutouts: WorktopCutout[] };
/** Выбор столешницы в панели и в меню правой кнопки: материал + толщина одним пунктом (у акрила толщина = подклейка). */
export const WORKTOP_CHOICES: readonly { id: string; label: string; material: WorktopMaterial; thickness: number; hint: string }[] = [
  { id: "compact-12", label: "Компакт 12", material: "compact", thickness: 12, hint: "Компакт-плита HPL 12 мм: торец без кромки, шлифованный" },
  { id: "acrylic-12", label: "Акрил 12", material: "acrylic", thickness: 12, hint: "Акриловый камень 12 мм в один слой, без подклейки" },
  { id: "quartz-20", label: "Кварц 20", material: "quartz", thickness: 20, hint: "Кварцевый агломерат 20 мм, торец полированный" },
  { id: "postforming-38", label: "ЛДСП 38", material: "postforming", thickness: 38, hint: "ЛДСП постформинг 38 мм (СКИФ) — как сейчас" },
  { id: "acrylic-40", label: "Акрил 40", material: "acrylic", thickness: 40, hint: "Акриловый камень 12 мм с подклейкой до 40 мм" },
];
/** Камень и компакт: толщина задана материалом, кромки ЛДСП нет — торец обрабатывается (строка сметы «обработка торца»). */
export const worktopSolid = (w: WorktopSpec) => w.material === "compact" || w.material === "acrylic" || w.material === "quartz";
/** Допустимые толщины материала с фиксированной толщиной; у старых материалов — не ограничено (поле «Толщина» 12–60). */
export const WORKTOP_THICKNESS: Partial<Record<WorktopMaterial, number[]>> = { compact: [12], acrylic: [12, 40], quartz: [20] };
/** Сменить материал: толщина — по материалу (акрил сохраняет выбранную подклейку), высота модуля = толщина. */
export function setWorktopMaterial(m: Module, material: WorktopMaterial, thickness?: number) {
  const fixed = WORKTOP_THICKNESS[material], cur = m.worktop!.thickness;
  // с компакта/акрила/кварца на старый материал (ЛДСП, постформинг, камень) — 38 мм (KITCHEN.worktopThickness), а не 12/20/40:
  // иначе «Компакт 12» → «ЛДСП» давал деталь ЛДСП 12 мм в раскрое (ревью 19.10); ЛДСП тоже 38, не 32 (баг Макса по демо 20.10)
  const t = thickness ?? (fixed ? (fixed.includes(cur) ? cur : fixed[0]) : worktopSolid(m.worktop!) ? KITCHEN.worktopThickness : cur);
  m.worktop = { ...m.worktop!, material, thickness: t };
  m.height = t;
}

